function validate([operations, args]) {
  if (!Array.isArray(operations) || !Array.isArray(args) || operations.length !== args.length) return 'operations and arguments need the same length.';
  if (operations[0] !== 'SnapshotArray' || !Array.isArray(args[0]) || args[0].length !== 1) return 'Start with SnapshotArray(length).';
  const length = args[0][0];
  if (!Number.isInteger(length) || length < 1 || length > 50000) return 'length is a whole number from 1 to 5 * 10^4.';
  if (operations.length - 1 > 50000) return 'At most 5 * 10^4 calls to set, snap and get.';
  const goodIndex = (index) => Number.isInteger(index) && index >= 0 && index < length;
  let snaps = 0;
  for (let i = 1; i < operations.length; i++) {
    const a = args[i];
    if (!Array.isArray(a)) return 'Each call needs an argument list.';
    if (operations[i] === 'set') {
      if (a.length !== 2 || !goodIndex(a[0])) return 'set needs an index from 0 to length - 1 and a value.';
      if (!Number.isInteger(a[1]) || a[1] < 0 || a[1] > 1000000000) return 'set values are between 0 and 10^9.';
    } else if (operations[i] === 'snap') {
      if (a.length !== 0) return 'snap takes no arguments.';
      snaps++;
    } else if (operations[i] === 'get') {
      if (a.length !== 2 || !goodIndex(a[0])) return 'get needs an index from 0 to length - 1 and a snap_id.';
      if (!Number.isInteger(a[1]) || a[1] < 0 || a[1] >= snaps) return 'get can only ask for a snapshot that was already taken.';
    } else {
      return 'Only set, snap and get can follow the constructor.';
    }
  }
  return null;
}

