class SnapshotArray {
  constructor(length) {
    this.history = Array.from({ length }, () => [[-1, 0]]);
    this.snapId = 0;
  }

  set(index, val) {
    const records = this.history[index];
    const last = records[records.length - 1];
    if (last[0] === this.snapId) {
      last[1] = val;
    } else {
      records.push([this.snapId, val]);
    }
  }

  snap() {
    this.snapId++;
    return this.snapId - 1;
  }

  get(index, snap_id) {
    const records = this.history[index];
    let left = 0;
    let right = records.length - 1;
    while (left < right) {
      const mid = (left + right + 1) >> 1;
      if (records[mid][0] <= snap_id) {
        left = mid;
      } else {
        right = mid - 1;
      }
    }
    return records[left][1];
  }
}

