class SnapshotArray {
  constructor(length) {
    this.values = new Array(length).fill(0);
    this.saved = [];
  }
  set(index, val) {
    this.values[index] = val;
  }
  snap() {
    this.saved.push(this.values.slice());
    return this.saved.length - 1;
  }
  get(index, snap_id) {
    return this.saved[snap_id][index];
  }
}

