function generate(rand, size) {
  const int = (low, high) => low + Math.floor(rand() * (high - low + 1));
  const large = size === 'large';
  const length = large ? (rand() < 0.5 ? 50000 : int(1, 30)) : int(1, 5);
  const maxVal = rand() < 0.6 ? 9 : 1000000000;
  const calls = large ? 499 : int(1, 15);
  const setRate = 0.25 + rand() * 0.4;
  const snapRate = 0.1 + rand() * 0.3;
  const operations = ['SnapshotArray'];
  const args = [[length]];
  let snaps = 0;
  for (let i = 0; i < calls; i++) {
    const roll = rand();
    if (roll < setRate) {
      operations.push('set');
      args.push([int(0, length - 1), int(0, maxVal)]);
    } else if (roll < setRate + snapRate || snaps === 0) {
      operations.push('snap');
      args.push([]);
      snaps++;
    } else {
      operations.push('get');
      args.push([int(0, length - 1), int(0, snaps - 1)]);
    }
  }
  return [operations, args];
}
